import{_ as d,o as e,c as r,a2 as a}from"./chunks/framework.CFuv5BrO.js";const h=JSON.parse('{"title":"ADR 与关键决策","description":"Hearth 的 ADR 索引与最终判断。","frontmatter":{"title":"ADR 与关键决策","description":"Hearth 的 ADR 索引与最终判断。","outline":[2,3]},"headers":[],"relativePath":"delivery/decisions.md","filePath":"delivery/decisions.md","lastUpdated":1793706118000}'),i={name:"delivery/decisions.md"};function l(o,t,c,n,p,A){return e(),r("div",null,[...t[0]||(t[0]=[a('<p class="eyebrow">DECISIONS</p><h1 id="adr-与关键决策" tabindex="-1">ADR 与关键决策 <a class="header-anchor" href="#adr-与关键决策" aria-label="Permalink to &quot;ADR 与关键决策&quot;">​</a></h1><p class="lead">把不可轻易反转的产品与工程判断固化为可追踪的决策记录。</p><h2 id="adr-索引" tabindex="-1">ADR 索引 <a class="header-anchor" href="#adr-索引" aria-label="Permalink to &quot;ADR 索引&quot;">​</a></h2><p>以下是建议的首批架构决策。状态为 <code>Accepted</code> 的应尽早写入仓库，后续变更通过新 ADR 记录。</p><table tabindex="0"><thead><tr><th>ADR</th><th>决策</th><th>状态</th><th>主要后果</th></tr></thead><tbody><tr><td>ADR-001</td><td>Hearth 是单用户、自托管、本地优先的个人 Agent OS</td><td>Accepted</td><td>不做企业 IAM；优先本地状态和可迁移</td></tr><tr><td>ADR-002</td><td>Event Log 是唯一事实源，UI/索引/记忆是投影</td><td>Accepted</td><td>需要事件 schema、重放和 migration</td></tr><tr><td>ADR-003</td><td>早期使用 SQLite WAL 和单写者，不引入微服务</td><td>Accepted</td><td>降低运维；需要 lease 和水平扩展预案</td></tr><tr><td>ADR-004</td><td>采用模块化单体，执行器通过统一协议接入</td><td>Accepted</td><td>边界靠接口和测试保证，而非网络拆分</td></tr><tr><td>ADR-005</td><td>使用 Executor 多执行器模型，不追求单体万能 Agent</td><td>Accepted</td><td>需要能力声明、路由和统一结果契约</td></tr><tr><td>ADR-006</td><td>Codex 是首个外部执行器，可做代码、研究、文档和 Shell，但不是产品本体</td><td>Accepted</td><td>需要适配器、版本锁定和降级路径</td></tr><tr><td>ADR-007</td><td>自研 Execution Gateway、Policy、Broker；集成 Sandbox/Runtime 内核</td><td>Accepted</td><td>不自研容器/虚拟化；需要统一 Sandbox Provider</td></tr><tr><td>ADR-008</td><td>所有外部副作用走类型化 Effect、outbox、幂等键和 Receipt</td><td>Accepted</td><td>增加实现复杂度，但避免重复和不可审计</td></tr><tr><td>ADR-009</td><td>高风险动作需要 Mandate 和 Approval；执行器不能扩大权限</td><td>Accepted</td><td>增加交互，但建立信任边界</td></tr><tr><td>ADR-010</td><td>记忆分五类，带来源、置信度、敏感度、预算和遗忘</td><td>Accepted</td><td>需要记忆维护和用户界面</td></tr><tr><td>ADR-011</td><td>自进化只产生候选技能，经 Shadow/Canary/评估/回滚后晋升</td><td>Accepted</td><td>需要评测集和版本管理</td></tr><tr><td>ADR-012</td><td>手机优先 PWA，先做查看/审批/接管/发起/通知</td><td>Accepted</td><td>暂不做完整移动 Agent；降低发布成本</td></tr><tr><td>ADR-013</td><td>Token Governor 和 Context Compiler 是核心架构，不是后置优化</td><td>Accepted</td><td>需要统一计量、预算和上下文组装</td></tr><tr><td>ADR-014</td><td>学 OpenClaw/Hermes 的模式，不 fork 其产品底座</td><td>Accepted</td><td>需要自建 Gateway、Memory、Evolution 协议</td></tr><tr><td>ADR-015</td><td>Human Executor 和 takeover 是一等能力</td><td>Accepted</td><td>需要实时界面、审计和恢复</td></tr><tr><td>ADR-016</td><td>不做企业多租户、公开 Agent 市场和计费</td><td>Accepted</td><td>聚焦个人体验和自托管</td></tr><tr><td>ADR-017</td><td>当前只接入 Codex，其他外部 Agent 暂不纳入产品范围</td><td>Accepted（临时）</td><td>保留 Executor 接口，避免绑定</td></tr><tr><td>ADR-018</td><td>模型可替换，本地模型可选，不训练基础模型</td><td>Accepted</td><td>需要模型目录、路由和评估</td></tr><tr><td>ADR-019</td><td>采用 MVP-first 的纵向切片交付；前端从 Stage 0 起进入每个增量</td><td>Accepted</td><td>不允许后端先行、最后补界面；阶段验收必须包含浏览器路径</td></tr><tr><td>ADR-020</td><td>路线图只以能力门槛和增量顺序推进，不使用周/月排期</td><td>Accepted</td><td>不承诺完成日期；进度以真实任务、恢复和评测证据衡量</td></tr></tbody></table><hr><h2 id="最终判断" tabindex="-1">最终判断 <a class="header-anchor" href="#最终判断" aria-label="Permalink to &quot;最终判断&quot;">​</a></h2><h2 id="最终判断-1" tabindex="-1">最终判断 <a class="header-anchor" href="#最终判断-1" aria-label="Permalink to &quot;最终判断&quot;">​</a></h2><p>回到最初的争论：是只写控制层，把执行交给外部 Agent，还是把 runtime 和 sandbox 也全部自己写？</p><p><strong>产品路线应采用前者，但不是简单的“薄封装”。</strong></p><p>Hearth 自己写：</p><ul><li>控制面；</li><li>Durable Harness；</li><li>事件日志；</li><li>审批与幂等；</li><li>Context Compiler 与 Token Governor；</li><li>Memory OS；</li><li>Evolution OS；</li><li>Execution Gateway；</li><li>Credential Broker；</li><li>任务卡、审批、产物和手机入口。</li></ul><p>Hearth 集成：</p><ul><li>Codex；</li><li>模型 API 或本地模型；</li><li>容器/微虚拟机/Sandbox 内核；</li><li>Playwright；</li><li>文档解析与转换库；</li><li>邮件、日历、云盘等官方 API。</li></ul><p>Hearth 只为学习保留：</p><ul><li>最小事件循环和 session tree；</li><li>上下文压缩原型；</li><li>单机 Sandbox 包装；</li><li>路由和评估实验。</li></ul><p>这样既能深入学习 Agent Runtime、Harness、Sandbox、Gateway、Memory 和 Evolution，又不会把项目生命耗在重新实现容器、虚拟化和模型推理引擎上。</p><p>Codex 的定位也应同样清楚：</p><blockquote><p><strong>Codex 是 Hearth 目前最强、最通用的外部执行器之一，可以写代码，也可以做调研、长文档、报告、表格和复杂文件工作；但它并不局限于代码，也不是 Hearth 的本体。邮件、日历、网页、桌面、文档确定性处理和人类责任，分别由并列的 Connector、Browser、GUI、Document/Data 和 Human Executor 承担。</strong></p></blockquote><p>最终，Hearth 的护城河不是“拥有一个更强的模型”，而是：</p><ul><li>知道什么时候不该调用模型；</li><li>知道该给执行器什么最小上下文；</li><li>知道哪些动作必须经过谁的授权；</li><li>知道如何证明任务真的完成；</li><li>知道失败后如何恢复；</li><li>知道什么应该记住，什么应该遗忘；</li><li>知道什么时候应该停下来，把注意力还给人。</li></ul><p>如果这些做成了，Hearth 就不只是一个 Agent 套壳，而是一台真正属于个人的、长期可靠的数字工作系统。</p><p>最后是交付判断：</p><blockquote><p><strong>先做出一个能在真实浏览器里每天使用的最小产品，再把它逐步长成 Personal Agent OS。</strong></p></blockquote><p>Stage 0 用原型验证产品叙事，Stage 1 尽早交付 MVP，此后每个增量都同时交付界面、后端、验证和恢复。路线图不设开发时间限制，不以“第几周”证明进展，只以真实任务、可恢复性和用户是否愿意继续使用来证明方向正确。</p>',26)])])}const u=d(i,[["render",l]]);export{h as __pageData,u as default};
